    body: JSON.stringify({ filterGroups, properties: ["name", "domain", "website"], limit: 50 }),
    hasCriteria: filterGroups.length > 0,
    domain: domain || null,
    domainUrl: domain ? "https://" + domain : null,
    name: name || null,
    address: clean(p.address) || null,
